   443|export async function saveVariableValue(
   444|  name: string,
   445|  value: string,
   446|  env: EnvSnapshot = process.env,
   447|  fetchImpl: FetchLike = fetch,
   448|): Promise<{ ok: boolean; httpStatus: number | null; detail: string; masked: string | null; valueLength: number }> {
   449|  const spec = RUNTIME_VARIABLE_SPECS.find((s) => s.name === name);
   450|  if (!spec) return { ok: false, httpStatus: null, detail: 'Unknown variable.', masked: null, valueLength: 0 };
   451|
   452|  const nextValue = typeof value === 'string' ? value.trim() : '';
   453|  if (nextValue.length === 0) {
   454|    return { ok: false, httpStatus: null, detail: 'A non-empty value is required to save.', masked: null, valueLength: 0 };
   455|  }
   456|
   457|  const key = trimmed(env.RENDER_API_KEY);
   458|  const serviceId = trimmed(env.RENDER_SERVICE_ID);
   459|  if (!key || !serviceId) {
   460|    return { ok: false, httpStatus: null, detail: 'RENDER_API_KEY + RENDER_SERVICE_ID required to save into the Render runtime secret store.', masked: null, valueLength: 0 };
   461|  }
   462|
   463|  const r = await probe(
   464|    fetchImpl,
   465|    `https://api.render.com/v1/services/${encodeURIComponent(serviceId)}/env-vars/${encodeURIComponent(name)}`,
   466|    {
   467|      method: 'PUT',
   468|      headers: { Authorization: `Bearer ${key}`, Accept: 'application/json', 'Content-Type': 'application/json' },
   469|      body: JSON.stringify({ value: nextValue }),
   470|    },
   471|    10000,
   472|  );
   473|  return {
   474|    ok: r.ok,
   475|    httpStatus: r.status,
   476|    detail: r.ok
   477|      ? `Saved ${name} to the Render service env. A redeploy is required for the new value to take effect in the running container.`
   478|      : `Render env update returned HTTP ${r.status ?? 'network-error'}.`,
   479|    masked: r.ok ? maskSecret(nextValue) : null,
   480|    valueLength: nextValue.length,
   481|  };
